CREATE TABLE public.families (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 150), slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9-]+$'), aliases text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.families TO anon, authenticated;
GRANT ALL ON public.families TO service_role;
ALTER TABLE public.families ENABLE ROW LEVEL SECURITY;
CREATE POLICY families_public_read ON public.families FOR SELECT TO anon, authenticated USING (true);
CREATE INDEX families_name_idx ON public.families (lower(name));
CREATE TABLE public.history_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(trim(title)) > 0), author_or_organization text, url text CHECK (url IS NULL OR url ~ '^https?://'), publication_year integer, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.history_sources TO anon, authenticated;
GRANT ALL ON public.history_sources TO service_role;
ALTER TABLE public.history_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY sources_public_read ON public.history_sources FOR SELECT TO anon, authenticated USING (published);
CREATE TABLE public.family_histories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES public.families(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL CHECK(length(trim(body)) > 0), published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.family_histories TO anon, authenticated;
GRANT ALL ON public.family_histories TO service_role;
ALTER TABLE public.family_histories ENABLE ROW LEVEL SECURITY;
CREATE POLICY histories_public_read ON public.family_histories FOR SELECT TO anon, authenticated USING (published);
CREATE INDEX family_histories_family_idx ON public.family_histories(family_id);
CREATE TABLE public.family_history_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), history_id uuid NOT NULL REFERENCES public.family_histories(id) ON DELETE CASCADE, source_id uuid NOT NULL REFERENCES public.history_sources(id), pages text, UNIQUE(history_id, source_id));
GRANT SELECT ON public.family_history_sources TO anon, authenticated;
GRANT ALL ON public.family_history_sources TO service_role;
ALTER TABLE public.family_history_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY citations_public_read ON public.family_history_sources FOR SELECT TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.family_histories h WHERE h.id = history_id AND h.published) AND EXISTS (SELECT 1 FROM public.history_sources s WHERE s.id = source_id AND s.published));
CREATE INDEX family_history_sources_source_idx ON public.family_history_sources(source_id);
CREATE TABLE public.participant_marks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES public.families(id), user_id uuid, country text NOT NULL CHECK(length(trim(country)) > 0), city text, latitude double precision CHECK(latitude BETWEEN -90 AND 90), longitude double precision CHECK(longitude BETWEEN -180 AND 180), consent_to_publish boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT (id, family_id, country, city, latitude, longitude, consent_to_publish, status) ON public.participant_marks TO anon, authenticated;
GRANT ALL ON public.participant_marks TO service_role;
ALTER TABLE public.participant_marks ENABLE ROW LEVEL SECURITY;
CREATE POLICY marks_public_read ON public.participant_marks FOR SELECT TO anon, authenticated USING(status = 'approved' AND consent_to_publish);
CREATE POLICY marks_owner_read ON public.participant_marks FOR SELECT TO authenticated USING(user_id = (SELECT auth.uid()));
CREATE INDEX participant_marks_family_idx ON public.participant_marks(family_id);
CREATE INDEX participant_marks_user_idx ON public.participant_marks(user_id);
COMMENT ON TABLE public.participant_marks IS 'Participant locations only; pending is the default. No public writes in stage 2.';